BEGIN; INSERT INTO clinics(id,name,clerk_org_id) VALUES('ci-e21-a','CI E21 A','ci_e21_org_a'),('ci-e21-b','CI E21 B','ci_e21_org_b') ON CONFLICT(id) DO NOTHING; INSERT INTO integration_connections(id,clinic_id,provider_key,interface_type,environment) VALUES('ci-e21-conn-a','ci-e21-a','synthetic.ehr','fhir','sandbox') ON CONFLICT(id) DO NOTHING; SET ROLE authenticated; SELECT set_config('app.clerk_org_id','ci_e21_org_a',false); DO 'BEGIN IF NOT EXISTS(SELECT 1 FROM integration_connections WHERE id=''ci-e21-conn-a'') THEN RAISE EXCEPTION ''tenant A cannot read connection''; END IF; END'; SELECT set_config('app.clerk_org_id','ci_e21_org_b',false); DO 'BEGIN IF EXISTS(SELECT 1 FROM integration_connections WHERE id=''ci-e21-conn-a'') THEN RAISE EXCEPTION ''cross-tenant integration read''; END IF; END'; RESET ROLE; ROLLBACK;